// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.io.File;
import java.io.IOException;

import org.eclipse.rdf4j.sail.nativerdf.btree.RecordIterator;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

class TripleStoreExplicitnessTest {

	@TempDir
	File dataDir;

	@ParameterizedTest(name = "background={0}, initially explicit={1}")
	@CsvSource({ "0, true", "0, false", "256, true", "256, false" })
	void committedExplicitnessChangeDoesNotLeaveTransactionFlags(int background, boolean initiallyExplicit)
			throws IOException {
		try (TripleStore store = createStore(background, initiallyExplicit)) {
			boolean explicit = initiallyExplicit;
			for (int i = 0; i < 3; i++) {
				store.startTransaction();
				changeExplicitness(store, explicit);
				assertStatement(store, explicit, false, true);
				store.commit();
				explicit = !explicit;
				assertCommittedStatement(store, explicit);
			}
		}
	}

	@ParameterizedTest(name = "background={0}, initially explicit={1}")
	@CsvSource({ "0, true", "0, false", "256, true", "256, false" })
	void transactionReadsReflectExplicitnessChange(int background, boolean initiallyExplicit) throws IOException {
		try (TripleStore store = createStore(background, initiallyExplicit)) {
			store.startTransaction();
			changeExplicitness(store, initiallyExplicit);
			assertStatement(store, !initiallyExplicit, true, true);
			assertStatement(store, initiallyExplicit, true, false);
			assertStatement(store, initiallyExplicit, false, true);
			assertStatement(store, !initiallyExplicit, false, false);
			store.rollback();
		}
	}

	@ParameterizedTest(name = "background={0}")
	@ValueSource(ints = { 0, 256 })
	void explicitlyReaddingDemotedStatementMakesItExplicit(int background) throws IOException {
		try (TripleStore store = createStore(background, true)) {
			store.startTransaction();
			changeExplicitness(store, true);
			store.commit();

			store.startTransaction();
			store.storeTriple(1, 2, 3, 4, true);
			store.commit();
			assertCommittedStatement(store, true);
		}
	}

	@ParameterizedTest(name = "background={0}")
	@ValueSource(ints = { 0, 256 })
	void newlyAddedExplicitStatementCanBeRemovedAndReinferred(int background) throws IOException {
		try (TripleStore store = createStore(background, false)) {
			store.startTransaction();
			store.removeTriplesByContext(1, 2, 3, 4, false);
			store.commit();

			store.startTransaction();
			store.storeTriple(1, 2, 3, 4, true);
			store.removeTriplesByContext(1, 2, 3, 4, true);
			store.storeTriple(1, 2, 3, 4, false);
			assertStatement(store, false, true, true);
			assertStatement(store, true, true, false);
			store.commit();
			assertCommittedStatement(store, false);
		}
	}

	@ParameterizedTest(name = "background={0}, initially explicit={1}")
	@CsvSource({ "0, true", "0, false", "256, true", "256, false" })
	void removalUsesExplicitnessInsideTheTransaction(int background, boolean initiallyExplicit) throws IOException {
		try (TripleStore store = createStore(background, initiallyExplicit)) {
			store.startTransaction();
			changeExplicitness(store, initiallyExplicit);
			assertEquals(1L, store.removeTriplesByContext(1, 2, 3, 4, !initiallyExplicit)
					.values()
					.stream()
					.mapToLong(Long::longValue)
					.sum());
			assertStatement(store, true, true, false);
			assertStatement(store, false, true, false);
			store.commit();
			assertStatement(store, true, false, false);
			assertStatement(store, false, false, false);
		}
	}

	@ParameterizedTest(name = "background={0}, initially explicit={1}")
	@CsvSource({ "0, true", "0, false", "256, true", "256, false" })
	void removingPreviousExplicitnessPreservesChangedStatement(int background, boolean initiallyExplicit)
			throws IOException {
		try (TripleStore store = createStore(background, initiallyExplicit)) {
			store.startTransaction();
			changeExplicitness(store, initiallyExplicit);
			assertEquals(0L, store.removeTriplesByContext(1, 2, 3, 4, initiallyExplicit)
					.values()
					.stream()
					.mapToLong(Long::longValue)
					.sum());
			assertStatement(store, !initiallyExplicit, true, true);
			store.commit();
			assertCommittedStatement(store, !initiallyExplicit);
		}
	}

	@ParameterizedTest(name = "background={0}, initially explicit={1}")
	@CsvSource({ "0, true", "0, false", "256, true", "256, false" })
	void rollbackRestoresExplicitness(int background, boolean initiallyExplicit) throws IOException {
		try (TripleStore store = createStore(background, initiallyExplicit)) {
			store.startTransaction();
			changeExplicitness(store, initiallyExplicit);
			store.rollback();
			assertCommittedStatement(store, initiallyExplicit);
		}
	}

	private TripleStore createStore(int background, boolean explicit) throws IOException {
		TripleStore store = new TripleStore(dataDir, "spoc,posc");
		store.startTransaction();
		store.storeTriple(1, 2, 3, 4, explicit);
		// A single record forces full-index commit scanning. Background records keep the small update cache valid.
		for (int i = 0; i < background; i++) {
			store.storeTriple(i + 100, 20, 30, 40, true);
		}
		store.commit();
		return store;
	}

	private void changeExplicitness(TripleStore store, boolean wasExplicit) throws IOException {
		if (wasExplicit) {
			store.removeTriplesByContext(1, 2, 3, 4, true);
		}
		store.storeTriple(1, 2, 3, 4, !wasExplicit);
	}

	private void assertCommittedStatement(TripleStore store, boolean explicit) throws IOException {
		try (RecordIterator records = store.getTriples(1, 2, 3, 4)) {
			byte[] record = records.next();
			assertNotNull(record);
			assertEquals(explicit ? TripleStore.EXPLICIT_FLAG : 0, record[TripleStore.FLAG_IDX],
					"A committed record must not retain transaction flags");
			assertNull(records.next());
		}
		assertStatement(store, explicit, false, true);
		assertStatement(store, !explicit, false, false);
		assertStatement(store, explicit, true, true);
		assertStatement(store, !explicit, true, false);
	}

	private void assertStatement(TripleStore store, boolean explicit, boolean readTransaction, boolean present)
			throws IOException {
		// Exercise both configured indexes, including the effective explicitness filter used inside transactions.
		for (int[] pattern : new int[][] { { 1, -1, -1, -1 }, { -1, 2, 3, 4 } }) {
			try (RecordIterator records = store.getTriples(pattern[0], pattern[1], pattern[2], pattern[3], explicit,
					readTransaction)) {
				if (present) {
					assertNotNull(records.next(), "Expected " + (explicit ? "explicit" : "inferred") + " statement");
				}
				assertNull(records.next(), "Unexpected " + (explicit ? "explicit" : "inferred") + " statement");
			}
		}
	}
}
